    function mkSep(){return $('<div class="erg-group-separator">')}

    function mkHdr(lv,mode,label,sub,ck,count){
      var ic=!!collapsed_groups[ck];
      var countLabel=count===1?"1 transaksi":count+" transaksi";
      return $('<div class="erg-group-header erg-lvl-'+lv+'" data-group-level="'+lv+'" data-chain-key="'+esc(ck)+'" data-collapsed="'+(ic?"1":"0")+'">'
        +'<div class="erg-group-left"><div class="erg-group-toggle">'+(ic?"&#9658;":"&#9660;")+'</div>'
        +'<div class="erg-group-text"><div class="erg-group-title">'+esc(label)+'</div><div class="erg-group-sub">'+esc(sub||"")+'</div></div></div>'
        +'<div class="erg-group-right">'
        +'<div class="erg-group-count">'+esc(countLabel)+'</div>'
        +'<div class="erg-group-badge">'+esc(mode)+'</div>'
        +'</div></div>');
    }

    function doCollapse($h){
      var lv=parseInt($h.attr("data-group-level"),10);
      collapsed_groups[$h.attr("data-chain-key")]=true;
      $h.attr("data-collapsed","1").find(".erg-group-toggle").html("&#9658;");
      var $n=$h.next();
      while($n.length){if($n.hasClass("erg-group-header")&&parseInt($n.attr("data-group-level"),10)<=lv)break;$n.addClass("erg-hidden-by-collapse");$n=$n.next()}
    }
    function doExpand($h){
      var lv=parseInt($h.attr("data-group-level"),10);
      delete collapsed_groups[$h.attr("data-chain-key")];
      $h.attr("data-collapsed","0").find(".erg-group-toggle").html("&#9660;");
      var $n=$h.next();
      while($n.length){
        if($n.hasClass("erg-group-header")){
          var nl=parseInt($n.attr("data-group-level"),10);if(nl<=lv)break;
          $n.removeClass("erg-hidden-by-collapse");
          if($n.attr("data-collapsed")==="1"){var $s=$n.next();while($s.length){if($s.hasClass("erg-group-header")&&parseInt($s.attr("data-group-level"),10)<=nl)break;$s.addClass("erg-hidden-by-collapse");$s=$s.next()}}
        }else{$n.removeClass("erg-hidden-by-collapse")}
        $n=$n.next()
      }
      listview.$result.find(".erg-group-header[data-collapsed='1']").each(function(){doCollapse($(this))})
    }
    function bindEv(){listview.$result.find(".erg-group-header").off("click.erg").on("click.erg",function(e){e.stopPropagation();$(this).attr("data-collapsed")==="1"?doExpand($(this)):doCollapse($(this))})}

    function applyGrouping(){
      if(is_rendering||!listview.$result)return;
      if(!selected_groups.length){rmv();return}
      is_rendering=true;
      try{
        rmv();
        var rs=[];
        getRows().each(function(){var $r=$(this),n=getDN($r);if(!n)return;var d=getDoc(n),dv=d?d[DATE_FIELD]:null,dObj=pd(dv);rs.push({$r:$r,n:n,dObj:dObj,ts:dObj?dObj.getTime():0})});
        rs.sort(function(a,b){return a.ts!==b.ts?a.ts-b.ts:a.n.localeCompare(b.n)});
        if(rs.length){var $p=rs[0].$r.parent();rs.forEach(function(r){$p.append(r.$r)})}

        // Hitung count per chainKey
        var countMap={};
        rs.forEach(function(item){
          var chain=selected_groups.map(function(mode){var g=gv(item.dObj,mode);return{mode:mode,key:String(g.key),label:g.label}});
          chain.forEach(function(g,idx){
            var ck=chain.slice(0,idx+1).map(function(x){return x.mode+":"+x.key}).join("||");
            countMap[ck]=(countMap[ck]||0)+1;
          });
        });

        var pk=[],pt=null;
        rs.forEach(function(item){
          var chain=selected_groups.map(function(mode){var g=gv(item.dObj,mode);return{mode:mode,key:String(g.key),label:g.label}});
          if(!chain.length)return;
          var tk=chain[0].mode+":"+chain[0].key;
          chain.forEach(function(g,idx){
            var lv=idx+1,ck=chain.slice(0,lv).map(function(x){return x.mode+":"+x.key}).join("||");
            if(pk[idx]!==ck){
              if(idx===0&&pt!==null&&tk!==pt)item.$r.before(mkSep());
              var sub=idx===0?"Group by "+g.mode:chain.slice(0,idx).map(function(x){return x.label}).join(" / ");
              var count=countMap[ck]||0;
              item.$r.before(mkHdr(lv,g.mode,g.label,sub,ck,count));
              pk[idx]=ck;for(var j=idx+1;j<pk.length;j++)pk[j]=null
            }
          });
          pt=tk
        });
        bindEv();
        if(!Object.keys(collapsed_groups).length)listview.$result.find(".erg-group-header").each(function(){doCollapse($(this))});
        else listview.$result.find(".erg-group-header[data-collapsed='1']").each(function(){doCollapse($(this))})
      }finally{is_rendering=false}
    }

    function sched(d){clearTimeout(apply_timer);apply_timer=setTimeout(applyGrouping,d||400)}
    function updDisp(){
      if(selected_groups.length){$("#erg-text").text(selected_groups.join(" + ")).removeClass("is-placeholder");$("#erg-clr").show()}
      else{$("#erg-text").text("Group By").addClass("is-placeholder");$("#erg-clr").hide()}
    }
    function syncChk(){$("#erg-dd .erg-opt-check").each(function(){$(this).prop("checked",selected_groups.indexOf($(this).val())>-1)})}
    function buildUI(){
      var opts=GROUP_OPTIONS.map(function(o){return'<label class="erg-opt"><input type="checkbox" class="erg-opt-check" value="'+o+'"><span>'+o+'</span></label>'}).join("");
      return $('<div id="erg-wrap">'
        +'<div id="erg-select"><span id="erg-text" class="is-placeholder">Group By</span></div>'
        +'<div id="erg-chevron"><svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg></div>'
        +'<span id="erg-clr">&times;</span>'
        +'<div id="erg-dd"><div class="erg-dd-title">Pilih level grouping</div>'+opts
        +'<div class="erg-dd-actions">'
        +'<button class="erg-dd-btn" id="erg-sa">All</button>'
        +'<button class="erg-dd-btn" id="erg-ca">Clear</button>'
        +'<button class="erg-dd-btn primary" id="erg-ap">Apply</button>'
        +'</div></div></div>');
    }
    function attachUI($w){
      $w.on("click","#erg-select",function(e){e.stopPropagation();syncChk();$("#erg-dd").toggle()});
      $w.on("click","#erg-sa",function(e){e.stopPropagation();$("#erg-dd .erg-opt-check").prop("checked",true)});
      $w.on("click","#erg-ca",function(e){e.stopPropagation();$("#erg-dd .erg-opt-check").prop("checked",false)});
      $w.on("click","#erg-ap",function(e){
        e.stopPropagation();
        selected_groups=GROUP_OPTIONS.filter(function(o){return $("#erg-dd .erg-opt-check[value='"+o+"']").prop("checked")});
        collapsed_groups={};updDisp();$("#erg-dd").hide();sched(300)
      });
      $w.on("click","#erg-clr",function(e){e.stopPropagation();selected_groups=[];collapsed_groups={};updDisp();rmv();syncChk()});
      $(document).off("click.erg").on("click.erg",function(){$("#erg-dd").hide()});
      $w.on("click","#erg-dd",function(e){e.stopPropagation()})
    }
    function injectUI(){
      $("#erg-wrap").remove();
      var $a=$('[data-fieldname="'+ANCHOR_FIELD+'"].frappe-control');
      if(!$a.length)return false;
      var $w=buildUI();$a.after($w);attachUI($w);updDisp();return true
    }
    if(!listview.__erg_patched){
      listview.__erg_patched=true;
      var oR=listview.render,oRf=listview.refresh;
      listview.render=function(){var r=oR.apply(this,arguments);sched(500);return r};
      listview.refresh=function(){var r=oRf.apply(this,arguments);sched(600);return r}
    }
    frappe.after_ajax(function(){
      if(!injectUI()){var n=0;var iv=setInterval(function(){n++;if(injectUI()||n>20)clearInterval(iv)},200)}
      sched(700)
    })
  }
};

