  function getWeekOfMonth(dt) { const f = new Date(dt.getFullYear(), dt.getMonth(), 1); return Math.ceil((dt.getDate() + f.getDay()) / 7); }
  function getGroupValue(d, mode) {
    if (!d) return { key:"NO_DATE", label:"No Date" };
    const y=d.getFullYear(), m=d.getMonth(), day=d.getDate(), q=Math.floor(m/3)+1, w=getWeekOfMonth(d);
