const CONFIG = {
  "Expense Request": {
    DATE_FIELD:   "request_date",
    ANCHOR_FIELD: "allocation_mode",
  },
  "Purchase Invoice": {
    DATE_FIELD:   "posting_date",
    ANCHOR_FIELD: "supplier",
