    ANCHOR_FIELD: "payment_type",
  },
  "Journal Entry": {
    DATE_FIELD:   "posting_date",
    ANCHOR_FIELD: "voucher_type",
  },
  "Purchase Order": {
    DATE_FIELD:   "transaction_date",
    ANCHOR_FIELD: "supplier",
  },
  "Sales Order": {
    DATE_FIELD:   "transaction_date",
    ANCHOR_FIELD: "customer",
