function applyUniversalGroupBy(listview, doctype) {
  const cfg = CONFIG[doctype];
  if (!cfg) {
    console.warn("[GroupBy] Tidak ada config untuk:", doctype);
    return;
  }

  const DATE_FIELD   = cfg.DATE_FIELD;
  const ANCHOR_FIELD = cfg.ANCHOR_FIELD;
  const GROUP_OPTIONS = ["Year", "Quarter", "Month", "Week", "Day"];

  let selected_groups  = [];
  let collapsed_groups = {};
  let apply_timer      = null;
  let is_rendering     = false;

  // ── CSS ────────────────────────────────────────────────────
  if (!$("#erg-style").length) {
    $("head").append(`
      <style id="erg-style">
        .standard-filter-section.flex{
          display:flex !important;
          flex-wrap:wrap !important;
          align-items:center !important;
          gap:8px !important;
