        }
        #erg-clr{
          display:none;position:absolute;right:24px;top:50%;
          transform:translateY(-50%);cursor:pointer;color:#8d99a6;
          font-size:13px;z-index:3;line-height:1;
        }
        #erg-dd{
          display:none;position:absolute;top:calc(100% + 6px);left:0;
          background:#fff;border:1px solid #d1d8dd;border-radius:8px;
