        .erg-dd-btn{
          flex:1;border:1px solid #d1d8dd;background:#fff;color:#36414c;
          font-size:11px;border-radius:6px;padding:6px 8px;cursor:pointer;
        }
        .erg-dd-btn.primary{
          background:#2490ef;color:#fff;border-color:#2490ef;
        }
        .erg-dd-btn:hover{ background:#f5f7fa; }
        .erg-dd-btn.primary:hover{ background:#1a7fd4; }
        .erg-group-separator{ margin:20px 0 8px; border-top:2px solid #dbe3ea; }
        .erg-group-header{
          display:flex;align-items:center;justify-content:space-between;
          gap:10px;padding:10px 12px;margin:0 0 6px;
          background:#f7f9fb;border:1px solid #e3e8ee;
          border-radius:8px;cursor:pointer;user-select:none;
        }
        .erg-group-header:hover{ background:#f2f6fa; }
        .erg-group-left{ display:flex;align-items:center;gap:10px;min-width:0; }
        .erg-group-toggle{ width:18px;text-align:center;color:#8d99a6;font-size:12px;flex:0 0 auto; }
        .erg-group-title{ font-size:12px;font-weight:700;color:#36414c;line-height:1.3; }
        .erg-group-sub{ font-size:11px;color:#8d99a6;line-height:1.3;margin-top:2px; }
        .erg-group-right{ display:flex;align-items:center;gap:8px;flex-shrink:0; }
        .erg-group-count{
          font-size:11px;color:#68717d;
          background:#edf2f7;border:1px solid #dde5ee;
          border-radius:999px;padding:2px 8px;
          white-space:nowrap;
        }
        .erg-group-badge{
          flex:0 0 auto;font-size:10px;font-weight:600;color:#68717d;
          background:#edf2f7;border:1px solid #dde5ee;
          border-radius:999px;padding:3px 8px;
        }
        .erg-lvl-1{ margin-top:10px; }
        .erg-lvl-2{ margin-left:18px;background:#fbfcfd; }
        .erg-lvl-3{ margin-left:36px;background:#fcfdfe; }
        .erg-lvl-4{ margin-left:54px;background:#fff; }
        .erg-lvl-5{ margin-left:72px;background:#fff; }
        .erg-hidden-by-collapse{ display:none !important; }
      </style>
    `);
  }

  // ── Date helpers ────────────────────────────────────────────
  const MONTH_NAMES = [
    "Januari","Februari","Maret","April","Mei","Juni",
    "Juli","Agustus","September","Oktober","November","Desember"
  ];

  function parseDate(s) {
    if (!s) return null;
    return frappe.datetime.str_to_obj(s);
  }

  function getWeekOfMonth(dt) {
    const first = new Date(dt.getFullYear(), dt.getMonth(), 1);
    return Math.ceil((dt.getDate() + first.getDay()) / 7);
  }

  function getGroupValue(dateObj, mode) {
    if (!dateObj) return { key:"NO_DATE", label:"No Date" };
    const y = dateObj.getFullYear();
    const m = dateObj.getMonth();
    const d = dateObj.getDate();
    const q = Math.floor(m / 3) + 1;
    const w = getWeekOfMonth(dateObj);

    if (mode==="Year")    return { key:`${y}`,                                           label:`${y}` };
    if (mode==="Quarter") return { key:`${y}-Q${q}`,                                     label:`Q${q} ${y}` };
    if (mode==="Month")   return { key:`${y}-${String(m+1).padStart(2,"0")}`,             label:`${MONTH_NAMES[m]} ${y}` };
    if (mode==="Week")    return { key:`${y}-${String(m+1).padStart(2,"0")}-W${w}`,       label:`Minggu ${w} — ${MONTH_NAMES[m]} ${y}` };
    if (mode==="Day")     return { key:`${y}-${String(m+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`, label:`${String(d).padStart(2,"0")} ${MONTH_NAMES[m]} ${y}` };
    return { key:"UNKNOWN", label:"Unknown" };
  }

  // ── DOM helpers ─────────────────────────────────────────────
  function esc(t) { return frappe.utils.escape_html(t == null ? "" : String(t)); }

  function getRowElements() {
    if (!listview.$result) return $();
    return listview.$result.find(".list-row-container").filter(function(){
      return !!getDocName($(this));
    });
  }

  function getDocName($row) {
    return $row.attr("data-name") ||
           $row.find("[data-name]").first().attr("data-name") ||
           $row.find(".list-subject a").first().attr("data-name") || null;
  }

  function getDoc(name) {
    if (!Array.isArray(listview.data)) return null;
    return listview.data.find(d => d.name === name) || null;
  }

  // ── Grouping DOM ────────────────────────────────────────────
  function removeArtifacts() {
    if (!listview.$result) return;
    listview.$result.find(".erg-group-header,.erg-group-separator").remove();
    listview.$result.find(".erg-hidden-by-collapse").removeClass("erg-hidden-by-collapse");
  }

  function makeSep() { return $('<div class="erg-group-separator">'); }

  function makeHeader(level, mode, label, subtext, chainKey, count) {
    const isCol = !!collapsed_groups[chainKey];
    const countLabel = count === 1 ? "1 transaksi" : `${count} transaksi`;
    return $(`
      <div class="erg-group-header erg-lvl-${level}"
           data-group-level="${level}"
           data-chain-key="${esc(chainKey)}"
           data-collapsed="${isCol ? "1":"0"}">
        <div class="erg-group-left">
          <div class="erg-group-toggle">${isCol ? "▸":"▾"}</div>
          <div class="erg-group-text">
            <div class="erg-group-title">${esc(label)}</div>
            <div class="erg-group-sub">${esc(subtext||"")}</div>
          </div>
        </div>
        <div class="erg-group-right">
          <div class="erg-group-count">${esc(countLabel)}</div>
          <div class="erg-group-badge">${esc(mode)}</div>
        </div>
      </div>
    `);
  }

  function collapseHeader($h) {
    const lv = parseInt($h.attr("data-group-level"), 10);
    collapsed_groups[$h.attr("data-chain-key")] = true;
    $h.attr("data-collapsed","1").find(".erg-group-toggle").text("▸");
    let $n = $h.next();
    while ($n.length) {
      if ($n.hasClass("erg-group-header") && parseInt($n.attr("data-group-level"),10) <= lv) break;
      $n.addClass("erg-hidden-by-collapse"); $n = $n.next();
    }
  }

  function expandHeader($h) {
    const lv = parseInt($h.attr("data-group-level"), 10);
    delete collapsed_groups[$h.attr("data-chain-key")];
    $h.attr("data-collapsed","0").find(".erg-group-toggle").text("▾");
    let $n = $h.next();
    while ($n.length) {
      if ($n.hasClass("erg-group-header")) {
        const nl = parseInt($n.attr("data-group-level"), 10);
        if (nl <= lv) break;
        $n.removeClass("erg-hidden-by-collapse");
        if ($n.attr("data-collapsed") === "1") {
          let $s = $n.next();
          while ($s.length) {
            if ($s.hasClass("erg-group-header") && parseInt($s.attr("data-group-level"),10) <= nl) break;
            $s.addClass("erg-hidden-by-collapse"); $s = $s.next();
          }
        }
      } else { $n.removeClass("erg-hidden-by-collapse"); }
      $n = $n.next();
    }
    listview.$result.find(".erg-group-header[data-collapsed='1']").each(function(){ collapseHeader($(this)); });
  }

  function bindCollapseEvents() {
    listview.$result.find(".erg-group-header")
      .off("click.ergcollapse")
      .on("click.ergcollapse", function(e) {
        e.stopPropagation();
        $(this).attr("data-collapsed") === "1" ? expandHeader($(this)) : collapseHeader($(this));
      });
  }

  function applyGrouping() {
    if (is_rendering || !listview.$result || !selected_groups.length) {
      if (!selected_groups.length) removeArtifacts();
      return;
    }
    is_rendering = true;
    try {
      removeArtifacts();

      // Sort rows by date
      const rows = [];
      getRowElements().each(function() {
        const $row = $(this);
        const name = getDocName($row);
        if (!name) return;
        const doc  = getDoc(name);
        const dv   = doc ? doc[DATE_FIELD] : null;
        const dObj = parseDate(dv);
        rows.push({ $row, name, dv, dObj, ts: dObj ? dObj.getTime() : 0 });
      });
      rows.sort((a, b) => a.ts !== b.ts ? a.ts - b.ts : a.name.localeCompare(b.name));

      // Reorder DOM
      if (rows.length) {
        const $parent = rows[0].$row.parent();
        rows.forEach(r => $parent.append(r.$row));
      }

      // Hitung count per chainKey
      const countMap = {};
      rows.forEach(function(item) {
        const chain = selected_groups.map(function(mode) {
          const g = getGroupValue(item.dObj, mode);
          return { mode, key: String(g.key), label: g.label };
        });
        chain.forEach(function(g, idx) {
          const partialKey = chain.slice(0, idx + 1).map(x => `${x.mode}:${x.key}`).join("||");
          countMap[partialKey] = (countMap[partialKey] || 0) + 1;
        });
      });

      // Insert headers
      let prevKeys = [];
      let prevTop  = null;

      rows.forEach(function(item) {
        const chain = selected_groups.map(function(mode) {
          const g = getGroupValue(item.dObj, mode);
          return { mode, key: String(g.key), label: g.label };
        });
        if (!chain.length) return;

        const topKey = `${chain[0].mode}:${chain[0].key}`;

        chain.forEach(function(g, idx) {
          const level      = idx + 1;
          const partialKey = chain.slice(0, level).map(x => `${x.mode}:${x.key}`).join("||");

          if (prevKeys[idx] !== partialKey) {
            if (idx === 0 && prevTop !== null && topKey !== prevTop) {
              item.$row.before(makeSep());
            }
            const sub   = idx === 0 ? "Group by " + g.mode : chain.slice(0, idx).map(x => x.label).join(" / ");
            const count = countMap[partialKey] || 0;
            item.$row.before(makeHeader(level, g.mode, g.label, sub, partialKey, count));
            prevKeys[idx] = partialKey;
            for (let j = idx+1; j < prevKeys.length; j++) prevKeys[j] = null;
          }
        });

        prevTop = topKey;
      });

      bindCollapseEvents();
      if (Object.keys(collapsed_groups).length === 0) {
        listview.$result.find(".erg-group-header").each(function(){ collapseHeader($(this)); });
      } else {
        listview.$result.find(".erg-group-header[data-collapsed='1']").each(function(){ collapseHeader($(this)); });
      }
    } finally { is_rendering = false; }
  }

  function scheduleApply(delay) {
    clearTimeout(apply_timer);
    apply_timer = setTimeout(applyGrouping, delay || 400);
  }

  // ── UI ──────────────────────────────────────────────────────
  function updateDisplay() {
    if (selected_groups.length) {
      $("#erg-text").text(selected_groups.join(" + ")).removeClass("is-placeholder");
      $("#erg-clr").show();
    } else {
      $("#erg-text").text("Group By").addClass("is-placeholder");
      $("#erg-clr").hide();
    }
  }

  function syncChecks() {
    $("#erg-dd .erg-opt-check").each(function(){
      $(this).prop("checked", selected_groups.includes($(this).val()));
    });
  }

  function buildWrap() {
    const opts = GROUP_OPTIONS.map(o =>
      `<label class="erg-opt"><input type="checkbox" class="erg-opt-check" value="${o}"><span>${o}</span></label>`
    ).join("");

    return $(`
      <div id="erg-wrap">
        <div id="erg-select">
          <span id="erg-text" class="is-placeholder">Group By</span>
        </div>
        <div id="erg-chevron">
          <svg class="icon icon-xs" aria-hidden="true"><use href="#icon-select"></use></svg>
        </div>
        <span id="erg-clr">×</span>
        <div id="erg-dd">
          <div class="erg-dd-title">Pilih level grouping</div>
          ${opts}
          <div class="erg-dd-actions">
            <button class="erg-dd-btn" id="erg-select-all">All</button>
            <button class="erg-dd-btn" id="erg-clear-all">Clear</button>
            <button class="erg-dd-btn primary" id="erg-apply">Apply</button>
          </div>
        </div>
      </div>
    `);
  }

  function attachEvents($wrap) {
    $wrap.on("click","#erg-select", function(e){ e.stopPropagation(); syncChecks(); $("#erg-dd").toggle(); });
    $wrap.on("click","#erg-select-all", function(e){ e.stopPropagation(); $("#erg-dd .erg-opt-check").prop("checked",true); });
    $wrap.on("click","#erg-clear-all",  function(e){ e.stopPropagation(); $("#erg-dd .erg-opt-check").prop("checked",false); });
    $wrap.on("click","#erg-apply", function(e) {
      e.stopPropagation();
      selected_groups = GROUP_OPTIONS.filter(o => $("#erg-dd .erg-opt-check[value='"+o+"']").prop("checked"));
      collapsed_groups = {};
      updateDisplay();
      $("#erg-dd").hide();
      scheduleApply(300);
    });
    $wrap.on("click","#erg-clr", function(e) {
      e.stopPropagation();
      selected_groups = []; collapsed_groups = {};
      updateDisplay(); removeArtifacts(); syncChecks();
    });
    $(document).off("click.erg").on("click.erg", function(){ $("#erg-dd").hide(); });
    $wrap.on("click","#erg-dd", function(e){ e.stopPropagation(); });
  }

  function injectUI() {
    $("#erg-wrap").remove();
    const $anchor = $(`[data-fieldname="${ANCHOR_FIELD}"].frappe-control`);
    if (!$anchor.length) return false;
    const $wrap = buildWrap();
    $anchor.after($wrap);
    attachEvents($wrap);
    updateDisplay();
    return true;
  }

  // ── Patch render & refresh ───────────────────────────────────
  if (!listview.__erg_patched) {
    listview.__erg_patched = true;
    const origRender  = listview.render;
    const origRefresh = listview.refresh;
    listview.render  = function(){ const r = origRender.apply(this,  arguments); scheduleApply(500); return r; };
    listview.refresh = function(){ const r = origRefresh.apply(this, arguments); scheduleApply(600); return r; };
  }

  // ── Boot ────────────────────────────────────────────────────
  frappe.after_ajax(function() {
    if (!injectUI()) {
      let n = 0;
      const iv = setInterval(function(){ n++; if(injectUI() || n > 20) clearInterval(iv); }, 200);
    }
    scheduleApply(700);
  });
}

