frappe.ui.form.on('Expense Request', {
    refresh: function(frm) {
        if (!frm._pi_dialog_patched) {
            frm._pi_dialog_patched = true;

            // Patch frappe.call
            const _orig_call = frappe.call.bind(frappe);
            frappe.call = function(opts) {
                const method = (typeof opts === 'object') ? (opts.method || '') : (opts || '');
                const is_pi = typeof method === 'string' &&
                    method.includes('create_purchase_invoice_from_request');

                if (is_pi && typeof opts === 'object') {
                    const _cb = opts.callback;
                    const _err = opts.error;

                    opts.callback = function(r) {
                        close_all_dialogs();
                        if (_cb) _cb(r);
                    };
                    opts.error = function(r) {
                        close_all_dialogs();
                        if (_err) _err(r);
                    };
                    opts.always = function() {
                        close_all_dialogs();
                    };
                }
                return _orig_call(opts);
            };

            // Patch frappe.xcall (promise-based)
            if (frappe.xcall) {
                const _orig_xcall = frappe.xcall.bind(frappe);
                frappe.xcall = function(method, params) {
                    const is_pi = typeof method === 'string' &&
                        method.includes('create_purchase_invoice_from_request');
                    const result = _orig_xcall(method, params);
                    if (is_pi && result && typeof result.then === 'function') {
                        return result.then(function(r) {
                            close_all_dialogs();
                            return r;
                        }).catch(function(e) {
                            close_all_dialogs();
                            throw e;
                        });
                    }
                    return result;
                };
            }
        }

        function close_all_dialogs() {
            try { frappe.dom.unfreeze(); } catch(e) {}
            try { if (cur_dialog) cur_dialog.hide(); } catch(e) {}
            try {
                frappe.ui.Dialog.instances && Object.values(frappe.ui.Dialog.instances).forEach(d => {
                    try { d.hide(); } catch(e) {}
                });
            } catch(e) {}
            $('.modal.show, .modal.fade.in').each(function() {
                $(this).modal('hide').remove();
            });
            $('.modal-backdrop').remove();
            $('body').removeClass('modal-open').css('padding-right', '');
            $('.freeze-message-container, #freeze-message').remove();
        }
    }
});

frappe.listview_settings['Delivery Order Towing'] = {
    get_indicator: function(doc) {
        // Use the custom Status field instead of docstatus
        const status_colors = {
            'Draft': 'red',
            'Submitted': 'blue',
            'Assigned': 'orange',
            'Picked Up': 'purple',
            'In Transit': 'yellow',
            'Delivered': 'green',
            'Cancelled': 'gray',
