        listview.page.add_field({
            fieldtype: 'Select',
            label: __('Status'),
            fieldname: 'status',
            options: [
                '',
                'Draft',
                'Submitted', 
                'Assigned',
                'Picked Up',
                'In Transit',
                'Delivered',
                'Completed',
                'Cancelled'
            ],
            change: function() {
                listview.refresh();
            }
        });
    }
};
